import{_ as e,o as r,c as t,a2 as n}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"供应商配置","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/providers.md","filePath":"zh/guide/providers.md","lastUpdated":1792716733000}'),a={name:"zh/guide/providers.md"};function s(i,o,l,g,c,h){return r(),t("div",null,[...o[0]||(o[0]=[n('<h1 id="供应商配置" tabindex="-1">供应商配置 <a class="header-anchor" href="#供应商配置" aria-label="Permalink to &quot;供应商配置&quot;">​</a></h1><p>本页逐一介绍支持的供应商：在哪里获取密钥、填在哪里、如何验证，以及最常见的错误。</p><p>所有密钥只保存在 Windows 凭据管理器中名为 <code>MeetCue</code> 的条目里，不会写入配置文件或日志；界面只知道某个密钥“已配置”还是“未配置”。</p><p>价格见<a href="/meetcue/zh/reference/pricing">价格参考</a>，以供应商官网为准。</p><h2 id="soniox" tabindex="-1">Soniox <a class="header-anchor" href="#soniox" aria-label="Permalink to &quot;Soniox&quot;">​</a></h2><p>语音识别，能很好地处理一句话里中英混说，自带句末检测。按音频小时计费。</p><ol><li><strong>获取密钥</strong>：登录 Soniox 控制台，创建一个 API 密钥。</li><li><strong>填写</strong>：<strong>设置 › 供应商与费用 › API 密钥 › Soniox 密钥</strong>，然后点 <strong>保存并验证</strong>。</li><li><strong>验证</strong>：验证成功后会列出你的账号可用的实时识别模型。</li><li><strong>端点</strong>：Soniox 提供多个端点。保持 <strong>自动</strong>，运行<a href="/meetcue/zh/guide/latency">延迟探测</a>选出最快的一个。</li></ol><p>常见错误：<a href="/meetcue/zh/troubleshooting/error-codes#mc-asr-001">MC-ASR-001</a>（密钥被拒绝）、<a href="/meetcue/zh/troubleshooting/error-codes#mc-asr-002">MC-ASR-002</a>（无法连接）。</p><h2 id="deepgram" tabindex="-1">Deepgram <a class="header-anchor" href="#deepgram" aria-label="Permalink to &quot;Deepgram&quot;">​</a></h2><p>流式语音识别，按音频分钟计费。</p><ol><li><strong>获取密钥</strong>：登录 Deepgram 控制台，打开你的项目，创建一个具有成员权限的 API 密钥。</li><li><strong>填写</strong>：<strong>设置 › 供应商与费用 › API 密钥 › Deepgram 密钥</strong>，然后点 <strong>保存并验证</strong>。</li><li><strong>验证</strong>：验证成功后会列出你的项目和可用的识别模型。</li><li><strong>语言</strong>：在 <strong>设置 › 音频 › 会议语言</strong> 中设置。选中中文时 Deepgram 使用普通话模型，否则使用多语言模型。</li></ol><p>常见错误：<a href="/meetcue/zh/troubleshooting/error-codes#mc-asr-001">MC-ASR-001</a>、<a href="/meetcue/zh/troubleshooting/error-codes#mc-asr-003">MC-ASR-003</a>（请求被限流）。</p><h2 id="anthropic" tabindex="-1">Anthropic <a class="header-anchor" href="#anthropic" aria-label="Permalink to &quot;Anthropic&quot;">​</a></h2><p>用 Claude 模型做问题检测和要点生成。</p><ol><li><strong>获取密钥</strong>：登录 Claude Console，打开 <strong>API keys</strong> 并创建密钥。为组织充值或添加付款方式。</li><li><strong>填写</strong>：<strong>设置 › 供应商与费用 › API 密钥 › Anthropic 密钥</strong>，然后点 <strong>保存并验证</strong>。</li><li><strong>验证</strong>：验证时从接口加载模型列表。价格表里有的模型显示价格，其余显示 <strong>价格未知</strong>。</li></ol><p>常见错误：<a href="/meetcue/zh/troubleshooting/error-codes#mc-llm-002">MC-LLM-002</a>（密钥被拒绝）、<a href="/meetcue/zh/troubleshooting/error-codes#mc-llm-003">MC-LLM-003</a>（请求被限流）、<a href="/meetcue/zh/troubleshooting/error-codes#mc-llm-004">MC-LLM-004</a>（模型不可用）。</p><h2 id="amazon-bedrock" tabindex="-1">Amazon Bedrock <a class="header-anchor" href="#amazon-bedrock" aria-label="Permalink to &quot;Amazon Bedrock&quot;">​</a></h2><p>通过你的 AWS 账号使用 Claude 模型。</p><ol><li><strong>开通模型</strong>：在 Amazon Bedrock 控制台中，切换到你要使用的 AWS 区域，为计划使用的 Anthropic 模型申请访问权限。</li><li><strong>获取密钥</strong>：在 Bedrock 控制台创建 Bedrock API 密钥。MeetCue 以 Bearer 令牌的方式发送它。</li><li><strong>填写</strong>：在 <strong>设置 › 供应商与费用</strong> 中填写开通模型的 <strong>AWS 区域</strong>，再在 <strong>Bedrock 密钥</strong> 处粘贴密钥并点 <strong>保存并验证</strong>。</li><li><strong>验证</strong>：这类密钥无法获取 Bedrock 的模型列表，MeetCue 会显示价格表中的 Claude 模型。如果账号里没有开通某个模型，使用时会报 <a href="/meetcue/zh/troubleshooting/error-codes#mc-llm-004">MC-LLM-004</a>。</li></ol><h2 id="openai-compatible-apis" tabindex="-1">OpenAI 兼容接口 <a class="header-anchor" href="#openai-compatible-apis" aria-label="Permalink to &quot;OpenAI 兼容接口 {#openai-compatible-apis}&quot;">​</a></h2><p>任何实现了 OpenAI Chat Completions 流式接口的服务，包括自建的模型服务。</p><ol><li><strong>Base URL</strong>：在 <strong>设置 › 供应商与费用</strong> 中填写以 <code>/v1</code> 结尾的地址，例如 <code>https://llm.example.com/v1</code>。</li><li><strong>密钥</strong>：在 <strong>OpenAI-compatible 密钥</strong> 处粘贴该服务的 API 密钥。不需要密钥的服务可以留空。</li><li><strong>验证</strong>：<strong>保存并验证</strong> 会加载 <code>/v1/models</code>。这些模型没有内置价格，请用 <strong>填写价格</strong> 补上，费用估算和预算才能生效。</li></ol><p>部分服务在流式输出时不返回 token 用量，此时其用量和费用显示为零。</p><h2 id="corporate-networks" tabindex="-1">公司网络 <a class="header-anchor" href="#corporate-networks" aria-label="Permalink to &quot;公司网络 {#corporate-networks}&quot;">​</a></h2><p>MeetCue 使用 Windows 证书库，公司安装的证书会被信任。所有连接（包括语音识别）都跟随 Windows 设置中手动配置的代理（<strong>网络和 Internet › 代理</strong>）。MeetCue 不会执行自动配置脚本；如果你的网络使用自动配置脚本，或要使用其他代理，请在 <strong>设置 › 供应商与费用 › 高级 › HTTPS 代理</strong> 中填写。如果连接失败并显示 <a href="/meetcue/zh/troubleshooting/error-codes#mc-net-001">MC-NET-001</a>，请看<a href="/meetcue/zh/troubleshooting/latency#company-network">延迟偏高</a>。</p>',25)])])}const m=e(a,[["render",s]]);export{p as __pageData,m as default};
